-- field: snapPoint
SELECT json_build_object('geoJson', (SELECT CASE WHEN (__geo.j->>'type') IN ('Point', 'LineString', 'Polygon', 'MultiPoint', 'MultiLineString', 'MultiPolygon', 'GeometryCollection') THEN CASE WHEN 'Geometry' || (__geo.j->>'type') || __geo.dims IN ('GeometryPoint') THEN CASE WHEN json_array_length(__geo.j->'coordinates') = 0 THEN NULL ELSE json_build_object('__typename', 'Geometry' || (__geo.j->>'type') || __geo.dims, 'srid', __geo.srid, 'x', __geo.j->'coordinates'->0, 'y', __geo.j->'coordinates'->1) END WHEN 'Geometry' || (__geo.j->>'type') || __geo.dims IN ('GeometryPointM', 'GeometryPointZ', 'GeometryPointZM') THEN CASE WHEN json_array_length(__geo.j->'coordinates') = 0 THEN NULL ELSE json_build_object('__typename', 'Geometry' || (__geo.j->>'type') || __geo.dims, 'srid', __geo.srid) END ELSE json_build_object('__typename', 'Geometry' || (__geo.j->>'type') || __geo.dims, 'srid', __geo.srid) END END FROM (SELECT ST_AsGeoJSON(__geo_v.g)::json AS j, ST_SRID(__geo_v.g) AS srid, CASE ST_Zmflag(__geo_v.g::geometry) WHEN 1 THEN 'M' WHEN 2 THEN 'Z' WHEN 3 THEN 'ZM' ELSE '' END AS dims FROM (SELECT __fn.v AS g) AS __geo_v) AS __geo WHERE __geo.j IS NOT NULL)) AS data
FROM (SELECT "public"."snap_point"("pt" => CASE WHEN left($1, 1) = '{' THEN ST_GeomFromGeoJSON($1) ELSE ST_GeomFromEWKT($1) END::"public"."geometry") AS v) AS __fn
-- args: ["{\"coordinates\":[1,2],\"type\":\"Point\"}"]

-- field: recordVisit
SELECT json_build_object('result', CASE WHEN __t_1 IS NULL THEN NULL ELSE json_build_object('visitId', __t_1."visit_id", 'spot', (SELECT CASE WHEN (__geo.j->>'type') IN ('Point', 'LineString', 'Polygon', 'MultiPoint', 'MultiLineString', 'MultiPolygon', 'GeometryCollection') THEN CASE WHEN 'Geometry' || (__geo.j->>'type') || __geo.dims IN ('GeometryPoint', 'GeometryPointM', 'GeometryPointZ', 'GeometryPointZM') THEN CASE WHEN json_array_length(__geo.j->'coordinates') = 0 THEN NULL ELSE json_build_object('__typename', 'Geometry' || (__geo.j->>'type') || __geo.dims, 'srid', __geo.srid) END ELSE json_build_object('__typename', 'Geometry' || (__geo.j->>'type') || __geo.dims, 'srid', __geo.srid) END END FROM (SELECT ST_AsGeoJSON(__geo_v.g)::json AS j, ST_SRID(__geo_v.g) AS srid, CASE ST_Zmflag(__geo_v.g::geometry) WHEN 1 THEN 'M' WHEN 2 THEN 'Z' WHEN 3 THEN 'ZM' ELSE '' END AS dims FROM (SELECT __t_1."spot" AS g) AS __geo_v) AS __geo WHERE __geo.j IS NOT NULL)) END) AS data
FROM "public"."record_visit"("spot" => CASE WHEN left($1, 1) = '{' THEN ST_GeomFromGeoJSON($1) ELSE ST_GeomFromEWKT($1) END::"public"."geometry") AS __t_1
-- args: ["{\"coordinates\":[1,2],\"type\":\"Point\"}"]

